class Guard(var x: Float = 0f) {
    fun update(dt: Float) { x += 20f * dt }          // the hook
}

LaunchedEffect(Unit) {                                // Compose, main dispatcher
    var prev = 0L
    while (isActive) {
        withFrameNanos { now ->                      // next display frame
            val dt = if (prev == 0L) 0f else (now - prev) / 1e9f
            prev = now
            for (g in guards) g.update(dt)           // the driver walk
        }
    }
}
